mapper.select:
select id, station_id, order_date, total_amount, total_num, create_time, update_time
from order_statistics

     and station_id = #{stationId}
     and order_date = #{orderDate}

        and order_date >= #{params.beginOrderDate}


        and order_date <= #{params.endOrderDate}


order by order_date desc, id desc

mapper.delete:
delete from order_statistics
where order_date >= #{orderDateBegin}
  and order_date <= #{orderDateEnd}
